// Original deterministic instrumentals dedicated to CC0 for tests. NOT singing or generated AI music.
export function testMusic(variant=0,seconds=6){const rate=24000,b=Buffer.alloc(44+rate*seconds*2);b.write('RIFF');b.writeUInt32LE(b.length-8,4);b.write('WAVEfmt ',8);b.writeUInt32LE(16,16);b.writeUInt16LE(1,20);b.writeUInt16LE(1,22);b.writeUInt32LE(rate,24);b.writeUInt32LE(rate*2,28);b.writeUInt16LE(2,32);b.writeUInt16LE(16,34);b.write('data',36);b.writeUInt32LE(b.length-44,40);const notes=[220,261.63,329.63,293.66];for(let i=0;i<rate*seconds;i++){const t=i/rate,phase=t%.5,f=notes[(Math.floor(t*2)+variant)%4]*(1+variant*.05),fade=Math.min(1,t*30,(seconds-t)*30),v=(Math.sin(2*Math.PI*f*t)*Math.exp(-phase*5)*.23+Math.sin(2*Math.PI*55*phase)*Math.exp(-phase*20)*.16)*fade;b.writeInt16LE(Math.round(v*32767),44+i*2);}return b;}
export const trackInput=(category='roses',variant=0)=>({category,title:`Teste instrumental ${variant+1}`,creator:'HubLoan test fixture',source:'server/tests/fixtures/live-music.mjs',license:'CC0-1.0 original test composition',commercialLiveRights:true,kind:'INSTRUMENTAL_TEST',costMinor:0});
